#include<bits/stdc++.h>
#define int long long
using namespace std;
int x,y,t,m;
bool vis[111][111][111];
int ans=INT_MAX;
void dfs(int a,int b,int k){
	if(vis[a][b][k]==1){
		return ;
	}
	vis[a][b][k]=1;
	if(k>=t){
		return ;
	}
	ans=min(ans,abs(m-a-b));
	
	dfs(x,b,k+1);
	dfs(0,b,k+1);
	dfs(a,y,k+1);
	dfs(a,0,k+1);
	if(a!=0){
		if(b!=y){
			if(y-b>=a){
				dfs(0,b+a,k+1);
			}else{
				dfs(a-y+b,y,k+1);
			}
		}	
	}
	if(b!=0){
		if(x!=a){
			if(x-a>=b){
				dfs(b+a,0,k+1);
			}else{
				dfs(x,b-x+a,k+1);
			}	
		}
	}
}
signed main() {
	ios::sync_with_stdio(0);cin.tie(0);	cout.tie(0);
	cin>>x>>y>>t>>m;
	dfs(0,0,0);
	cout<<ans;
	return 0;
}
